import { readFileSync, writeFileSync } from 'node:fs';
import { shippedDiagrams } from './shipped-diagrams.mjs';

// Generates the resources `@pensketch/mcp` serves, from the files that
// already hold them. The server publishes; it does not restate.
//
// Generated into source rather than read at runtime for two reasons. A tool
// that opens a file is a tool whose guarantees depend on where it is running,
// and this package asserts it opens none. And a generated file, regenerated
// in CI under the same tree-clean assertion as the goldens and the schema,
// cannot drift from what it mirrors — which is the failure this design set
// out to remove.
//
// Run locally: `npm run resources`.

const root = new URL('../', import.meta.url);
const out = new URL('packages/mcp/src/resources.generated.ts', root);
const read = (file) => readFileSync(new URL(file, root), 'utf8');

const KEYS = new Set(['pipeline', 'lifecycle', 'oauth']);

const examples = (await shippedDiagrams()).filter(({ key }) => KEYS.has(key));
if (examples.length !== KEYS.size) {
  console.error(
    `FAIL generate-resources: expected ${[...KEYS].join(', ')}, found ${examples.map((e) => e.key).join(', ')}`,
  );
  process.exit(1);
}

const TITLES = {
  pipeline: 'A continuous integration pipeline',
  lifecycle: 'An order lifecycle, with a self-transition drawn through raw',
  oauth: 'The OAuth 2.0 authorization code flow, in four lanes',
};

const body = `// Generated by tools/generate-resources.mjs. Do not edit.
//
// Each of these mirrors a file that exists for another reason, so that what
// an agent reads and what this repository ships cannot part company. CI
// regenerates and asserts the tree is unchanged.

/** The reference written for callers that are programs: docs/agents.md. */
export const SPEC = ${JSON.stringify(read('docs/agents.md'))};

/** The JSON Schema for a diagram, generated from the TypeScript types. */
export const SCHEMA = ${JSON.stringify(read('packages/core/schema/diagram.schema.json'))};

/**
 * The diagrams this repository ships, as the data that drew them — minus
 * \`raw\`, which holds functions. JSON turns those into nulls, so serving it
 * would advertise a key carrying nothing, and the lifecycle example uses it
 * for the self-transition. The JSON Schema drops it for the same reason.
 */
export const EXAMPLES = ${JSON.stringify(
  Object.fromEntries(
    examples.map(({ key, diagram, viewBox }) => {
      const { raw, ...data } = diagram;
      return [key, { title: TITLES[key], viewBox, diagram: data }];
    }),
  ),
  null,
  2,
)} as const;
`;

writeFileSync(out, body);
console.log(
  `wrote packages/mcp/src/resources.generated.ts (${examples.length} examples, ${Math.round(body.length / 1024)} KB)`,
);
